(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  function setVal(el, v) {
    const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    setter.call(el, v);
    el.dispatchEvent(new Event('input', {bubbles:true}));
    el.dispatchEvent(new Event('change', {bubbles:true}));
  }
  const vis = Array.from(document.querySelectorAll('input')).filter(i=>i.offsetParent!==null)
    .map(i=>({id:i.id, type:i.type, name:i.name, ph:i.placeholder, max:i.maxLength, cls:(i.className||'').toString().slice(0,40)}));
  const candidates = vis.filter(i => /pin/i.test(i.id||'') || i.maxLength===4 || /password|text/i.test(i.type))
    .filter(i => i.type!=='radio' && i.type!=='checkbox' && i.type!=='hidden' && i.type!=='tel');
  let filled = false;
  if (candidates.length) { setVal(candidates[0], '8751'); filled = true; await sleep(500); }
  const loginBtn = Array.from(document.querySelectorAll('button')).find(b => /^login$/i.test((b.innerText||'').replace(/\s+/g,' ').trim()) && b.offsetParent!==null);
  if (loginBtn) loginBtn.click();
  await sleep(11000);
  return JSON.stringify({filled, candidates: candidates.slice(0,3), allVis: vis.slice(0,8), url: location.href,
    errs: (Array.from(document.querySelectorAll('div,span,p,label')).map(e=>(e.innerText||'').replace(/\s+/g,' ').trim()).filter(t=>/wrong|invalid|incorrect|failed|mismatch/i.test(t) && t.length<100).slice(0,3)),
    txt: (document.body.innerText||'').replace(/\s+/g,' ').slice(0,220)});
})()
